        'variables_heading' => 'व्हेरिएबल्स &mdash; <code>{{path.to.field}}</code>',
        'variables_intro' => 'कोणतीही मुक्त-मजकूर क्रिया आर्ग्युमेंट ती सुरू करणाऱ्या घटनेतून मूल्ये घेऊ शकते. कोड हाताने टाइप करण्याची गरज नाही: प्रत्येक व्हेरिएबल-अनुकूल फील्डमध्ये <strong>व्हेरिएबल्ससह संपादित करा</strong> बटण आहे, जे बाजूला <strong>शोधता येणारी व्हेरिएबल्सची यादी</strong> असलेला प्रशस्त एडिटर उघडते — एकावर क्लिक करा आणि ते तुमच्या कर्सरवर येऊन पडते. थेट पूर्वावलोकन प्रत्येक कोडच्या जागी त्याचे खरे मूल्य टाकलेला पूर्ण मजकूर दाखवते.',
        'variables_scoped' => '<strong>तुम्हाला फक्त तेच व्हेरिएबल्स दिले जातात जे ट्रिगर प्रत्यक्षात भरू शकतो.</strong> हे दिसते त्यापेक्षा जास्त महत्त्वाचे आहे: गहाळ व्हेरिएबल त्रुटी देत नाही, तर शांतपणे <em>रिकाम्या स्ट्रिंग</em>मध्ये बदलते. म्हणून <code>knowledge.published</code> वरील ज्या वर्कफ्लोच्या संदेशात <code>{{ticket.subject}}</code> आहे तो अयशस्वी होणार नाही — तो विषयाच्या जागी फक्त रिकामे पोस्ट करेल, आणि तुम्हाला कधीच कळणार नाही. ज्ञान घटनेत तिकीट नसते, म्हणून पिकर तिकीट व्हेरिएबल्स अजिबात देत नाही, आणि तरीही तुम्ही एखादे टाइप केले तर ते रिकामे येईल असा इशारा फील्ड देते.',
        'variables_names' => '<strong>ID नव्हे, नाव वापरा.</strong> <code>{{ticket.priority_id}}</code> हे <code>4</code> असे दिसते &mdash; तुमचा Slack चॅनेल वाचणारे कोणीही अर्थ लावू शकणार नाही असा आकडा. म्हणून प्रत्येक लुकअप फील्डला वाचता येणारा जोडीदार आहे: <code>{{ticket.priority_name}}</code> हे <strong>गंभीर</strong> असे दिसते. पिकर नाव हा साधा पर्याय म्हणून दाखवते (<em>तिकीट &middot; प्राधान्य</em>) आणि संख्यात्मकावर <em>(id)</em> अशी खूण करते, कारण माणूस वाचणार असलेल्या संदेशात नाव जवळजवळ नेहमीच हवे असते. ID गरज पडेल तेव्हा उपलब्धच आहेत &mdash; अटीसाठी, किंवा त्यांची अपेक्षा करणाऱ्या स्वीकारणाऱ्या सिस्टमसाठी. बदल ट्रिगरवर तुम्हाला <code>{{old_priority_name}}</code> / <code>{{new_priority_name}}</code> देखील मिळतात, त्यामुळे "जास्त वरून गंभीर वर वाढवले" आपोआप लिहिले जाते.',
        'variables_number' => '<strong>ओळ ID नव्हे, संदर्भ क्रमांक द्या.</strong> <code>{{ticket.id}}</code> हा अंतर्गत डेटाबेस ID आहे (<code>83</code>) &mdash; विनंती करणाऱ्यासाठी अर्थहीन. <code>{{ticket.number}}</code> हा तो संदर्भ आहे जो ते प्रत्यक्षात तुम्हाला सांगतात (<code>ETC-623-64409</code>), आणि ईमेलच्या विषयात किंवा चॅट अलर्टमध्ये तोच हवा. <code>{{problem.number}}</code> साठीही तसेच. <strong>एक अपवाद:</strong> <em>तिकीट ID</em> क्रिया आर्ग्युमेंट <code>{{ticket.id}}</code> च राहिले पाहिजे &mdash; ते फील्ड इंजिनला <em>कोणत्या रेकॉर्डवर कृती करायची</em> हे सांगते, आणि ते ओळ ID वरून शोधते. माणूस वाचेल अशा शब्दांत क्रमांक वापरा; आतल्या जोडणीत ID ठेवा.',
        'variables_full' => 'ट्रिगरमध्ये पूर्ण रेकॉर्ड असल्यास, तुम्हाला <code>{{&lt;object&gt;.full}}</code> देखील मिळते &mdash; उदा. <code>{{ticket.full}}</code> &mdash; जे REST API जसे परत करते तशाच स्वरूपात संपूर्ण रेकॉर्ड JSON म्हणून एम्बेड करते. आणि <code>{{event}}</code> नेहमी सुरू झालेल्या ट्रिगरच्या नावात बदलते.',
        'variables_common' => 'तिकीट ट्रिगरसाठी सामान्य व्हेरिएबल्स:',
        'variables_li1' => '<code>{{ticket.id}}</code>, <code>{{ticket.subject}}</code>, <code>{{ticket.priority_id}}</code>, <code>{{ticket.status_id}}</code>',
        'variables_li2' => '<code>{{ticket.department_id}}</code>, <code>{{ticket.type_id}}</code>, <code>{{ticket.assigned_analyst_id}}</code>',
        'variables_li3' => '<code>{{ticket.owner_id}}</code>, <code>{{ticket.created_by}}</code>, <code>{{ticket.requester_email}}</code>',
        'variables_li4' => '<code>ticket.status_changed</code> / <code>ticket.priority_changed</code> साठी: तसेच <code>{{old_status_id}}</code>, <code>{{new_status_id}}</code>, <code>{{old_priority_id}}</code>, <code>{{new_priority_id}}</code>',
        'variables_li5' => '<code>ticket.assigned</code> साठी: तसेच <code>{{analyst_id}}</code>, <code>{{team_id}}</code>',
        'variables_tip' => '<strong>सर्वोत्तम पद्धत:</strong> क्रियेच्या <code>ticket_id</code> फील्डमध्ये विशिष्ट ID टाइप करण्याऐवजी डीफॉल्ट <code>{{ticket.id}}</code> ठेवा &mdash; म्हणजे वर्कफ्लो ठराविक तिकिटावर नव्हे, तर ज्या तिकिटाने तो सुरू केला त्यावर काम करतो.',
        'variables_chain_heading' => 'आधीच्या क्रियेने तयार केलेले वापरणे',
        'variables_chain_intro' => 'क्रिया क्रमाने चालतात, आणि नंतरची क्रिया आधीच्या क्रियेने काय केले याचा संदर्भ घेऊ शकते. त्यामुळेच <em>&ldquo;तिकीट तयार करा, मग व्यक्तीला तिचा तिकीट क्रमांक ईमेल करा&rdquo;</em> हे अशक्य न राहता एकच वर्कफ्लो बनते.',
        'variables_chain_last' => '<code>{{last.ticket_id}}</code> &mdash; या क्रियेच्या लगेच आधीच्या क्रियेने जे तयार केले ते.',
        'variables_chain_steps' => '<code>{{steps.1.ticket_number}}</code> &mdash; कॅनव्हासवर शेजारी दाखवलेल्या क्रमांकानुसार एखादी विशिष्ट क्रिया. तुम्हाला हवी असलेली क्रिया थेट आधीची नसेल तेव्हा हे वापरा.',
        'variables_chain_note' => 'ही जाणूनबुजून स्वतःच्या नावांखाली ठेवली आहेत, वर्कफ्लोच्या स्वतःच्या डेटावर लिहिण्याऐवजी. तिकीट तयार केल्याने <code>{{ticket.id}}</code> बदलले असते, तर तिकीट वर्कफ्लोमधील प्रत्येक नंतरची पायरी वर्कफ्लो सुरू करणाऱ्या तिकिटाऐवजी शांतपणे नव्या तिकिटाकडे निर्देश करू लागली असती.',
        'actions_forms_callout' => '<strong>फॉर्म देखील या क्रिया चालवू शकतात.</strong> वर्कफ्लो तयार करण्याऐवजी, फॉर्म उघडा आणि तो सबमिट, मंजूर किंवा नाकारला गेल्यावर काय घडावे हे सांगण्यासाठी त्याचा <strong>पुढे काय होते</strong> टॅब वापरा. इंजिन आणि क्रिया तेच आहेत, आणि रन त्याच अंमलबजावणी नोंदीत दिसतात &mdash; फॉर्म एडिटर हा फक्त त्या एका फॉर्मपुरता मर्यादित दुसरा प्रवेशमार्ग आहे. नियम अनेक फॉर्मवर लागू व्हायचा असेल तेव्हा येथे वर्कफ्लो तयार करा.',
        'ai_heading' => 'AI सह-लेखक',
        'ai_intro' => 'टूलबारवरील <strong>AI सह-लेखक</strong> वर क्लिक करा आणि वर्कफ्लोचे साध्या भाषेत वर्णन करा. AI एक संरचित प्रस्ताव देते &mdash; ट्रिगर, अटी, क्रिया &mdash; जो तुम्ही कॅनव्हासवर <em>लागू करा</em> किंवा <em>टाकून द्या</em>.',
        'ai_examples' => 'चांगले चालणारी उदाहरणे:',
        'ai_ex1' => '<em>"गंभीर-प्राधान्य तिकीट तयार झाल्यावर, \'P1 &mdash; कृपया 15 मिनिटांत प्रतिसाद द्या\' अशी टीप जोडा."</em>',
        'ai_ex2' => '<em>"<code>finance@acme.com</code> कडून तिकीट तयार झाल्यावर, ते मला नियुक्त करा आणि प्राधान्य जास्त करा."</em>',
        'ai_ex3' => '<em>"तिकीट बंद झाल्यावर, विनंती करणाऱ्याला आभार मानणारा आणि अभिप्राय मागणारा ईमेल पाठवा."</em>',
        'ai_catalogue' => 'AI ला इंजिनची संपूर्ण सूची माहीत असते &mdash; प्रत्येक ट्रिगर, अट ऑपरेटर, क्रिया आणि उपलब्ध लुकअप-टेबल मूल्ये &mdash; म्हणून ते फक्त प्रत्यक्षात चालतील अशाच गोष्टी सुचवू शकते. तुम्ही आधीच्या वर्कफ्लोमध्ये बदल करत गेलात (<em>"आता फक्त फायनान्स जुळवा"</em> / <em>"तिकीट ID नोंदवणारी क्रिया जोडा"</em>) तर ते पुन्हा सुरुवात करण्याऐवजी कॅनव्हासवर असलेले संपादित करते.',
        'ai_config' => 'प्रदाता (Anthropic / OpenAI), मॉडेल आणि API key <strong>Workflow &rarr; सेटिंग्ज &rarr; AI</strong> अंतर्गत कॉन्फिगर करा. की मॉड्यूलनुसार साठवल्या जातात, त्यामुळे बिलिंग आणि प्रवेश तपशीलवार ठरवता येतात.',
        'templates_heading' => 'टेम्पलेटपासून सुरुवात करा',
        'templates_intro' => 'वर्कफ्लो यादीवरील <strong>टेम्पलेटवरून नवीन</strong> बटण बहुतेक सर्व्हिस डेस्क प्रथम स्वयंचलित करतात त्या कामांच्या तयार पाककृतींची गॅलरी उघडते &mdash; नवीन तिकिटाची आपोआप पोचपावती, P1 वर टीमला सूचना, नवीन कर्मचारी फॉर्मचे IT, HR आणि सुविधा तिकिटांत विभाजन, बदल मंजूर झाल्यावर अंमलबजावणी कार्य तयार करणे. त्यातील चार <strong>वेळेवर आधारित</strong> आहेत: SLA भंग होण्यापूर्वी तिकीट <em>वाढवणे</em>, भंग झाल्यावर सूचना देणे, आणि करार किंवा मालमत्तेची वॉरंटी संपणार असल्याची आठवण करून देणे. एक निवडा आणि ती तुमच्या वर्कफ्लोमध्ये सामान्य, पूर्णपणे संपादनयोग्य वर्कफ्लो म्हणून कॉपी होते. त्यानंतर तिच्यात काहीही विशेष नसते: ती तुमची आहे, नाव बदला, पुन्हा जोडणी करा किंवा हटवा. गॅलरी <strong>श्रेणी</strong> आणि <strong>शोध</strong> नुसार फिल्टर होते &mdash; जो वर्णन, ट्रिगर आणि क्रियांपर्यंतही पोहोचतो, त्यामुळे <em>expiry</em>, <em>slack</em> किंवा <em>wipe</em> टाइप केल्यास नावात तो शब्द नसला तरी पाककृती सापडते.',
        'templates_lookups' => 'प्रत्येक इन्स्टॉलेशन स्वतःच्या स्थिती आणि प्राधान्यांना नावे देते, म्हणून टेम्पलेट ती थेट निश्चित करू शकत नाही. त्याऐवजी ते <em>"या इन्स्टॉलेशनमध्ये ज्याला बंद म्हणतात ते"</em> असे म्हणते आणि कॉपी करताना आम्ही खरे मूल्य शोधतो. जे आम्हाला जुळवता येत नाही &mdash; तुमच्याकडे नसलेले प्राधान्य, किंवा Slack webhook URL सारखे फक्त तुम्हालाच माहीत असलेले मूल्य &mdash; ते रिकामे ठेवले जाते आणि एडिटरच्या वरच्या बॅनरमध्ये यादी केले जाते, म्हणजे तुमच्याकडून काय बाकी आहे ते तुम्हाला नेमके दिसते.',
        'templates_scheduled' => 'चार वेळेवर आधारित पाककृतींसाठी एक <strong>शेड्यूल केलेले कार्य</strong> चालू असणे आवश्यक आहे, कारण त्या ज्याकडे पाहत असतात ती कोणतीही गोष्ट घटना नसते &mdash; SLA ची वेळ शांतपणे संपते तेव्हा कोणीही काहीही जतन करत नाही, म्हणून कोणीतरी जाऊन शोधावे लागते. क्रॉन शेड्यूल केले नसतील तर हे वर्कफ्लो सक्रिय राहून बसून राहतात आणि कधीच चालत नाहीत. दोन मुदतसमाप्ती स्मरणे देखील <strong>90, 30, 7 आणि 1 दिवस</strong> आधी चालतात, आणि प्रत्येक पाककृती 30-दिवसाच्या टप्प्यापुरती फिल्टर केलेली असते &mdash; प्रत्येक टप्प्यावर सूचना मिळवण्यासाठी ती अट बदला किंवा काढून टाका. <a href="#triggers">ट्रिगर</a> पहा.',
        'templates_callout' => 'क्लोन केलेले टेम्पलेट नेहमी <strong>बंद</strong> स्थितीत येते. तुम्ही ते वाचून, रिकाम्या जागा भरून आणि <em>सक्रिय</em> टिक करेपर्यंत त्यातील काहीही चालू शकत नाही &mdash; आणि ते नेमके काय करेल हे पाहण्यासाठी आधी <strong>ड्राय रन</strong> करू शकता.',
        'testing_heading' => 'जतन करणे आणि चाचणी',
        'testing_save' => 'टूलबारमधील स्थिती दिवा <em>जतन केलेले नाही</em> / <em>जतन करत आहे&hellip;</em> / <em>जतन केले</em> दाखवतो. कायम ठेवण्यासाठी <strong>जतन करा</strong> वर क्लिक करा. तुम्ही शून्य क्रियांसह अर्धवट मसुदे जतन करू शकता &mdash; तुम्हाला अडवले जाणार नाही, फक्त "या वर्कफ्लोमध्ये अद्याप क्रिया नाहीत" असा सौम्य इशारा मिळेल.',
        'testing_dry_heading' => 'ड्राय रन &mdash; ते काय करेल ते पाहा, न करता',
        'testing_dry_body' => '<strong>ड्राय रन</strong> अटी खऱ्या तपासतो, मग प्रत्येक क्रिया प्रत्यक्ष करण्याऐवजी तिचे <em>वर्णन</em> करतो. रन <em>अलीकडील रन</em> मध्ये <em>ड्राय रन</em> म्हणून खूण केलेला दिसतो, आणि <code>{{variables}}</code> आधीच भरलेल्या अवस्थेत तो करणार असलेल्या प्रत्येक क्रियेची यादी देतो &mdash; म्हणजे तुम्ही खरा ईमेल विषय, खरा चॅट संदेश, खरी टीप वाचता.',
        'testing_dry_safe' => 'काहीही लिहिले जात नाही, ईमेल केले जात नाही, रांगेत टाकले जात नाही किंवा पाठवले जात नाही: तिकिटात बदल नाहीत, टिपा नाहीत, webhook वितरणे नाहीत, आणि वर्कफ्लोचा रन काउंटर तसाच राहतो. त्यामुळे तो चालू वर्कफ्लोवर वापरणे सुरक्षित आहे &mdash; आणि नुकत्याच क्लोन केलेल्या टेम्पलेटवर प्रथम हेच करणे योग्य आहे. (कोणतेही साइनिंग सिक्रेट आउटपुटमध्ये परत दाखवण्याऐवजी लपवले जाते.)',
        'testing_log_heading' => 'अंमलबजावणी नोंद &mdash; प्रत्यक्षात काय घडले',
        'testing_log_why' => 'हे दिसते त्यापेक्षा जास्त महत्त्वाचे आहे. इंजिन <strong>जाणूनबुजून स्वतःच्या त्रुटी गिळते</strong> &mdash; बिघडलेला वर्कफ्लो तो सुरू करणारे तिकीट जतन होणे कधीही मोडू नये. ते योग्य आहे, आणि त्यामुळे अपयशी वर्कफ्लो अन्यथा <em>पूर्णपणे शांत</em> असतो. तुम्हाला काहीही कळत नाही. अंमलबजावणी नोंद आणि <strong>Watchtower वरील वर्कफ्लो कार्ड</strong> (जे गेल्या 24 तासांतील अपयश, लूप-संरक्षण थांबवणे आणि पुन्हा प्रयत्न सोडून दिलेले webhooks दाखवते) हीच ती शांतता मोडतात.',
        'testing_fire_heading' => 'टेस्ट फायर &mdash; प्रत्यक्ष चालवा',
        'testing_fire' => '<strong>टेस्ट फायर</strong> वर्कफ्लो स्वतःच्या अटींवरून तयार केलेल्या कृत्रिम पेलोडसह खरोखर चालवतो, त्यामुळे क्रिया मार्ग प्रत्यक्षात चालतो &mdash; तो खरोखरच तो ईमेल पाठवेल. निकाल स्थिती (<em>यशस्वी / अयशस्वी / वगळले</em>) आणि पूर्ण पायरी नोंदीसह <em>अलीकडील रन</em> मध्ये येतो.',
        'testing_real' => 'प्रत्यक्ष डेटावर चाचणी करण्यासाठी, ट्रिगर होणारी गोष्ट फक्त करा &mdash; तिकीट नेमा, त्याचे प्राधान्य बदला, इत्यादी. होस्ट मॉड्यूलकडून (तिकिटे) पाठवणी लाइव्ह आहे; अंमलबजावणी नोंदीत प्रत्येक फायर दिसतो.',
        'triggers_heading' => 'ट्रिगर सूची',
        'triggers_intro' => 'ही सूची आता <strong>प्रत्येक मॉड्यूलला व्यापते &mdash; 138 ट्रिगर आणि वाढत आहेत</strong>, सर्व जोडलेले आणि लाइव्ह. ते दोन प्रकारचे आहेत:',
        'triggers_time_heading' => 'वेळेवर आधारित ट्रिगर &mdash; आणि त्यांना लागणारा cron',
        'triggers_time_body' => 'बहुतेक ट्रिगर <strong>write path</strong> मधून फायर होतात: कोणीतरी तिकीट जतन केले, म्हणून फायर होण्यासाठी एक क्षण असतो. चार ट्रिगर तसे नाहीत. <code>sla.warning</code>, <code>sla.breached</code>, <code>contract.expiring</code> आणि <code>asset.warranty_expiring</code> या घटना नाहीतच &mdash; <em>काहीही घडले नाही, वेळ गेली</em> &mdash; म्हणून शेड्यूल केलेल्या जॉबने त्यांचा शोध घ्यावा लागतो.',
        'triggers_time_cron' => '<strong>हे cron शेड्यूल केलेले नसतील तर हे ट्रिगर कधीच फायर होत नाहीत.</strong> वर्कफ्लो सक्रिय असूनही काहीही करत बसेल. SLA घटना SLA breach-check cron मधून येतात (दर 5 मिनिटांनी); मुदतसंपण्याच्या घटना <code>cron/workflow_scheduled.php</code> मधून (तासाला एकदा पुरेसे). सेटअप: <code>docs/workflow-scheduled-cron-setup.md</code>, किंवा <a href="https://github.com/edmozley/freeitsm/wiki/Time-Based-Triggers" target="_blank" rel="noopener noreferrer">विकीवरील Time-Based Triggers</a>, ज्यात अजूनही खरी असलेली अट (breach झालेला SLA breach झालेलाच राहतो) दर काही मिनिटांनी पुन्हा फायर का होत नाही हेही स्पष्ट केले आहे.',
        'triggers_time_once' => 'वेळेवर आधारित अट <strong>खरीच राहते</strong> &mdash; breach झालेला SLA पाच मिनिटांनंतरही breach झालेलाच असतो &mdash; म्हणून FreeITSM एक खातेवही ठेवते आणि प्रत्येक परिस्थिती <strong>फक्त एकदाच</strong> फायर होते. त्याखालील गोष्ट बदलली की ती पुन्हा सज्ज होते: तिकिटाचे प्राधान्य वाढवा आणि त्याचे SLA लक्ष्य कमी होते, त्यामुळे नवीन, कडक मुदतीला पुन्हा एस्केलेट होण्याची मुभा असते. करार नूतनीकरण करा आणि पुढच्या वर्षीचे रिमाइंडर पुन्हा फायर होतात. मुदतसंपण्याचे ट्रिगर <strong>90, 30, 7 आणि 1 दिवस</strong> आधी फायर होतात, प्रत्येकासोबत <code>window_days</code> असते &mdash; म्हणून "फक्त 30 दिवसांना आठवण करा" ही केवळ एक अट आहे.',
        'triggers_family_domain' => '<strong>समृद्ध डोमेन घटना</strong> &mdash; संपूर्ण टाइप केलेल्या पेलोडसह अर्थपूर्ण जीवनचक्र क्षण: <code>ticket.created</code>, <code>ticket.status_changed</code>, <code>change.approved</code>, <code>problem.status_changed</code>, <code>task.completed</code>, <code>project.health_changed</code>, <code>service_status.incident_resolved</code>, <code>software.application_discovered</code> आणि अनेक इतर.',
        'triggers_family_forms' => '<strong>फॉर्म आणि कॅटलॉग विनंत्या</strong> &mdash; सामान्य फॉर्मसाठी <code>form.submitted</code> फायर होतो. मंजुरी लागणारा फॉर्म त्याऐवजी <code>catalogue_request.submitted</code> फायर करतो, आणि तुमच्या मंजूर करणाऱ्याने निर्णय दिल्यावर <code>catalogue_request.approved</code> किंवा <code>catalogue_request.rejected</code>. वेगळी घटना जाणूनबुजून आहे: त्यामुळे सबमिशनवर तिकीट तयार करणारा नियम तुम्ही मागितलेली मंजुरी ओलांडू शकत नाही. चारही सबमिट केलेली उत्तरे वाहून नेतात, म्हणून <code>{{submission.fields.Device type}}</code> प्रत्येक टप्प्यावर चालते, आणि चारही एका फॉर्मपुरते मर्यादित करता येतात.',
        'triggers_family_crud' => '<strong>तयार / अद्यतनित / हटवा घटना</strong> &mdash; प्रत्येक पुनर्वापरयोग्य रेकॉर्ड आणि सेटिंग्ज लुकअप <code>&lt;entity&gt;.created</code> / <code>.updated</code> / <code>.deleted</code> उत्सर्जित करतो: तिकिटे, मालमत्ता, बदल, समस्या, कार्ये, CMDB, करार &amp; पुरवठादार, दिनदर्शिका, सॉफ्टवेअर परवाने, नेटवर्क आकृत्या, आणि त्यांच्या सर्व सेटिंग्ज याद्या (स्थिती, प्राधान्ये, प्रकार, टॅग&hellip;).',
        'triggers_picker' => 'सूची डझनभर खोल असल्याने, एडिटरचा <strong>ट्रिगर पिकर शोधता येतो</strong> &mdash; फिल्टर करण्यासाठी टाइप करायला सुरू करा (<code>resolved</code>, <code>contract</code>, <code>delete</code>&hellip;). प्रत्येक घटना <strong>एकाच सामायिक write path</strong> मधून फायर होते, म्हणून बदल ब्राउझरमधून, REST API मधून किंवा दुसऱ्या वर्कफ्लोमधून आला तरी ती सारखीच वागते &mdash; ती भरकटू शकत नाही.',
        'failures_heading' => 'इंजिनमधील अपयश वेगळे ठेवले जातात',
        'failures_callout' => '<strong>चुकीचा वर्कफ्लो होस्ट मॉड्यूलची विनंती बिघडवू शकत नाही.</strong> प्रत्येक पाठवणी try/catch मध्ये गुंडाळलेली असते आणि प्रत्येक क्रियेचे अपयश साखळी न थांबवता अंमलबजावणी ओळीत नोंदवले जाते. वर्कफ्लो तुमच्या अपेक्षेप्रमाणे काम करत नसेल, तर वर्कफ्लोचा <em>अलीकडील रन</em> पॅनेल तपासा &mdash; अपयश तिथे मूळ त्रुटीसह दिसतात, ते चालू करणाऱ्या पृष्ठावर 500 म्हणून नाही.',
        'ahead_heading' => 'पुढे काय येणार',
        'ahead_li1' => '<strong>Tier 3 क्रिया</strong> &mdash; Microsoft Graph: <code>graph_add_to_group</code>, <code>graph_assign_license</code>, <code>graph_disable_user</code>. नवीन-सुरुवात करणारे / सोडून जाणारे ऑटोमेशन, जे सशुल्क ITSM सूटच्या तुलनेत या मॉड्यूलचे अस्तित्व सिद्ध करतात. विद्यमान टेनंट OAuth चौकटीचा पुनर्वापर करते.',
        'ahead_li4' => '<strong>ड्राय-रन मोड</strong> &mdash; खऱ्या घटनेवर वर्कफ्लो चालवा पण क्रिया पार पाडण्याऐवजी त्या <em>नोंदवा</em>. म्हणजे लाइव्ह करण्यापूर्वी काय घडले असते ते तुम्ही पाहू शकता.',
        'ahead_li5' => '<strong>स्टार्टर रेसिपी</strong> &mdash; सामान्य पॅटर्नसाठी क्लोन करता येणारे टेम्प्लेट: नवीन-सुरुवात ऑनबोर्डिंग, P1 घटना प्रतिसाद, SLA-breach एस्केलेशन, परवाना-नूतनीकरण रिमाइंडर.',
        'ahead_li6' => '<strong>Watchtower एकत्रीकरण</strong> &mdash; अयशस्वी रन लक्ष वेधणारी कार्डे म्हणून दिसतात.',
        'ahead_li7' => '<strong>वर्कफ्लो आवृत्ती व्यवस्थापन</strong> &mdash; मसुदा / प्रकाशित / रोलबॅक.',
        'ahead_li8' => '<strong>स्ट्रीमिंग AI सह-लेखक</strong> &mdash; कॅनव्हास तयार होताना claude.ai-शैलीचे लाइव्ह आउटपुट.',
    ],
